// Легаси-калькуляторы перечислены списком, калькуляторы V2 объявляют паритет
// сами — фактом наличия собственного копирайта для локали. Добавление
// калькулятора V2 больше не требует правки общего списка.
const globalCalculatorIds = new Set<string>([...fullParityCalculatorIds, ...v2FullParityIds]);

// Копирайт и вопросы категорий переехали в модули категорий. Здесь остались
// только производные карты: раньше на этом месте лежало около двух тысяч строк,
// в которые приходилось вписывать каждую новую категорию по семнадцати
// локалям. Теперь категория приносит свои переводы с собой.
const localizedCategories = Object.fromEntries(
  allLocales.map((locale) => [
    locale,
    Object.fromEntries(categoryDefinitions.map((definition) => [definition.id, definition.copy[locale]])),
  ]),
) as Record<Locale, Record<string, Omit<Category, 'id' | 'icon' | 'faq'>>>;

const localizedCategoryFaq = Object.fromEntries(
  allLocales.map((locale) => [
    locale,
    Object.fromEntries(categoryDefinitions.map((definition) => [definition.id, definition.faq[locale]])),
  ]),
) as Record<Locale, Record<string, FaqItem[]>>;

type CalcCopy = Pick<CalculatorDef,
  'name' | 'slug' | 'shortDescription' | 'longDescription' | 'seoTitle' | 'seoDescription' |
  'h1' | 'keywords' | 'howToUse' | 'howItWorks' | 'example' | 'faq' | 'disclaimer'
> & Pick<CalculatorDef, 'resultTitle'>;

function faq(topic: string): FaqItem[] {
  return [
    { q: `How accurate is this ${topic}?`, a: 'The result is a practical estimate based on the values you enter and the formula shown on the page.' },
    { q: `Does this ${topic} require an account?`, a: 'No. The calculator works in your browser and does not require registration.' },
    { q: `Can I share a ${topic} result?`, a: 'Yes. Use the share link to copy the current inputs in the page URL.' },
  ];
}

