const enUnits: Record<string, string> = {
  '₽': '$',
  'г': 'g',
  'мм': 'mm',
  '₽ годовых': '% yearly',
  '% годовых': '% yearly',
  'кг': 'kg',
  'см': 'cm',
  'м': 'm',
  'м²': 'm²',
  'л': 'L',
};

function localizeUnit(unit: string | undefined, locale: Locale): string | undefined {
  if (!unit || locale === 'ru') return unit;
  if (locale === 'uk') {
    const ukrainianUnits: Record<string, string> = {
      '₽': '₴',
      'мм': 'мм',
      '₽ годовых': '% річних',
      '% годовых': '% річних',
      'кг': 'кг',
      'г': 'г',
      'см': 'см',
      'м': 'м',
      'м²': 'м²',
      'л': 'л',
    };
    return ukrainianUnits[unit] ?? unit;
  }
  const currencyByLocale: Partial<Record<Locale, string>> = {
    en: '$',
    pl: 'zł',
    ro: 'lei',
    id: 'Rp',
    tr: '₺',
    vi: '₫',
    cs: 'Kč',
    uk: '₴',
    hu: 'Ft',
  };
  const currency = currencyByLocale[locale] ?? '€';
  return (enUnits[unit] ?? unit).replace('$', currency);
}

const optionLabelsByLocale = legacyOptionLabelsByLocale;

const fieldLabelsByLocale = legacyFieldLabelsByLocale;

function localizeField(field: Field, locale: Locale, calculatorId: string): Field {
  if (locale === 'ru') return { ...field };
  const fieldLabels = fieldLabelsByLocale[locale];
  const localizedOptions = optionLabelsByLocale[locale];
  return {
    ...field,
    // Сначала подпись, объявленная самим калькулятором, затем общая карта.
    // Имена полей вроде `mode` встречаются у многих калькуляторов сразу,
    // поэтому обращение к V2-локализации всегда идёт с идентификатором.
    label: lookupScoped(v2Localization, locale, calculatorId, 'fields', field.name)
      ?? fieldLabels[field.name] ?? field.label,
    unit: localizeUnit(field.unit, locale),
    help: field.help,
    options: field.options?.map((option) => ({
      ...option,
      label: lookupScoped(v2Localization, locale, calculatorId, 'options', option.value)
        ?? localizedOptions[option.value] ?? option.label,
    })),
  };
}

function localizeCategory(category: Category, locale: Locale): Category {
  if (locale === 'ru') {
    return {
      ...category,
      fullPath: undefined,
      slug: category.slug,
      faq: category.faq,
    } as Category;
  }

  const copy = localizedCategories[locale][category.id];
  return {
    ...category,
    ...copy,
    faq: localizedCategoryFaq[locale][category.id],
  };
}

function localizeCalculator(calculator: CalculatorDef, locale: Locale): CalculatorDef {
  const category = getCategoryById(calculator.category, locale);
  const fullPathPrefix = `/${locale}/${category.slug}`;

  if (locale === 'ru') {
    const localizedCalculator = {
      ...calculator,
      fullPath: `${fullPathPrefix}/${calculator.slug}/`,
      fields: calculator.fields.map((field) => localizeField(field, locale, calculator.id)),
    };
    const seoContent = getCalculatorSeoContent(localizedCalculator, locale);
    return { ...localizedCalculator, seoContent, faq: seoContent.faq };
  }

  const copy = buildLocalizedCalculatorCopy(calculator.id, locale);
  const localizedCalculator = {
    ...calculator,
    ...copy,
    resultTitle: copy.resultTitle ?? copy.name,
    category: calculator.category,
    fullPath: `${fullPathPrefix}/${copy.slug}/`,
    fields: calculator.fields.map((field) => localizeField(field, locale, calculator.id)),
    resultLabels: Object.fromEntries(
      Object.entries(calculator.resultLabels).map(([key, label]) => [
        key,
        // Сначала перевод, объявленный самим калькулятором: одна и та же русская
        // фраза у разных калькуляторов может значить разное.
        lookupScoped(v2Localization, locale, calculator.id, 'results', label)
          ?? localizedResultLabel(label, locale),
      ]),
    ),
    disclaimer: copy.disclaimer ?? (locale === 'uk'
      ? 'Результати є орієнтовними оцінками. Перед важливими рішеннями перевіряйте вихідні дані.'
      : 'Results are reference estimates. Verify the inputs before making important decisions.'),
    relatedCalculatorIds: calculator.relatedCalculatorIds.filter((id) => globalCalculatorIds.has(id)),
  };
  const seoContent = getCalculatorSeoContent(localizedCalculator, locale);
  return { ...localizedCalculator, seoContent, faq: seoContent.faq };
}

export function isLocale(value: string | undefined): value is Locale {
  return Boolean(value && (locales as readonly string[]).includes(value));
}

export function isCalculatorAvailableInLocale(id: string, locale: Locale): boolean {
  if (locale === 'ru') return true;
  // Немецкий каталог наполняется постепенно и содержит ровно то, для чего есть
  // настоящий немецкий текст. Требование глобального паритета сохраняется,
  // поэтому русскоязычные по существу калькуляторы сюда не попадают.
  if (locale === 'de') return germanCalculatorIds.has(id) && globalCalculatorIds.has(id);
  return globalCalculatorIds.has(id);
}

export function getCategories(locale: Locale): Category[] {
  return baseCategories.map((category) => localizeCategory(category, locale));
}

export function getCategoryById(id: CategoryId, locale: Locale): Category {
  const category = baseCategories.find((item) => item.id === id);
  if (!category) throw new Error(`Unknown category: ${id}`);
  return localizeCategory(category, locale);
}

export function getCategoriesBySlug(locale: Locale): Record<string, Category> {
  return Object.fromEntries(getCategories(locale).map((category) => [category.slug, category]));
}

export function getCalculators(locale: Locale): CalculatorDef[] {
  return baseCalculators
    .filter((calculator) => isCalculatorAvailableInLocale(calculator.id, locale))
    .map((calculator) => localizeCalculator(calculator, locale));
}

export function getCalculatorById(id: string, locale: Locale): CalculatorDef | undefined {
  const calculator = baseCalculators.find((item) => item.id === id);
  if (!calculator || !isCalculatorAvailableInLocale(id, locale)) return undefined;
  return localizeCalculator(calculator, locale);
}

export function getCalculatorsByCategory(categoryId: CategoryId, locale: Locale): CalculatorDef[] {
  return getCalculators(locale).filter((calculator) => calculator.category === categoryId);
}

export function getPopularCalculators(locale: Locale): CalculatorDef[] {
  return getCalculators(locale)
    .slice()
    .sort((a, b) => b.popularity - a.popularity || a.name.localeCompare(b.name, locale))
    .slice(0, 6);
}

export function getNewCalculators(locale: Locale): CalculatorDef[] {
  return getCalculators(locale)
    .filter((calculator) => calculator.isNew)
    .sort((a, b) => b.popularity - a.popularity || a.name.localeCompare(b.name, locale));
}

export function findCalculatorBySlug(
  locale: Locale,
  categorySlug: string,
  calculatorSlug: string,
): { calculator: CalculatorDef; category: Category } | undefined {
  const category = getCategories(locale).find((item) => item.slug === categorySlug);
  if (!category) return undefined;
  const calculator = getCalculatorsByCategory(category.id, locale)
    .find((item) => item.slug === calculatorSlug);
  return calculator ? { calculator, category } : undefined;
}

export function localeHome(locale: Locale): string {
  return `/${locale}/`;
}

export function localeCatalog(locale: Locale): string {
  return `/${locale}/calculators/`;
}

export function getEquivalentCalculatorPath(id: string, locale: Locale): string {
  const equivalent = getCalculatorById(id, locale);
  if (equivalent) return equivalent.fullPath;
  const calculator = baseCalculators.find((item) => item.id === id);
  return calculator ? getEquivalentCategoryPath(calculator.category, locale) : localeCatalog(locale);
}

export function getEquivalentCategoryPath(id: CategoryId, locale: Locale): string {
  return `/${locale}/${getCategoryById(id, locale).slug}/`;
}

export function getAlternatesForCalculator(id: string): AlternateLink[] {
  const links = locales
    .map((locale) => {
      const calculator = getCalculatorById(id, locale);
      return calculator ? { locale, href: calculator.fullPath } : undefined;
    })
    .filter(Boolean) as AlternateLink[];
  if (!isRuOnlyCalculator(id)) links.push({ locale: 'x-default', href: '/' });
  return links;
}

export function getAlternatesForCategory(id: CategoryId): AlternateLink[] {
  return [
    ...locales.map((locale) => ({ locale, href: getEquivalentCategoryPath(id, locale) })),
    { locale: 'x-default', href: '/' },
  ];
}

export function getAlternatesForPage(pathByLocale: Partial<Record<Locale, string>>): AlternateLink[] {
  const links: AlternateLink[] = locales.flatMap((locale) => {
    const href = pathByLocale[locale];
    return href ? [{ locale, href }] : [];
  });
  links.push({ locale: 'x-default', href: '/' });
  return links;
}

export function localizedResultText(value: string, locale: Locale): string {
  if (locale === 'ru') return value;
  const currencyByLocale: Partial<Record<Locale, string>> = {
    en: '$',
    pl: 'zł',
    ro: 'lei',
    id: 'Rp',
    tr: '₺',
    vi: '₫',
    cs: 'Kč',
    uk: '₴',
  };
  const currency = currencyByLocale[locale] ?? '€';
  return value
    .replaceAll('₽', currency)
    .replaceAll('ккал', 'kcal')
    .replaceAll('кг', 'kg')
    .replaceAll('мм', 'mm')
    .replaceAll('см', 'cm')
    .replaceAll('км/ч', 'km/h')
    .replaceAll('мес.', 'mo.')
    .replaceAll('лет', 'years')
    .replaceAll('дн.', 'days')
    .replaceAll('шт.', 'pcs.')
    .replaceAll('л', 'L');
}

